private float[] interpolateDirection(UEdge edge1, UEdge edge2, float t) {
    float length = (float) edge1.getLength();
    float length2 = (float) edge2.getLength();
    if (length <= 1.0E-4f && length2 <= 1.0E-4f) {
        return new float[]{0.0f, 0.0f};
    }
    if (length <= 1.0E-4f) {
        return edgeDirection(edge2);
    }
    if (length2 <= 1.0E-4f) {
        return edgeDirection(edge1);
    }
    float angle = (float) MathUtils.getAngle(edge1.mStart.x, edge1.mStart.y, edge1.mEnd.x, edge1.mEnd.y);
    double dNormalizeAngle = angle + (MathUtils.normalizeAngle(((float) MathUtils.getAngle(edge2.mStart.x, edge2.mStart.y, edge2.mEnd.x, edge2.mEnd.y)) - angle, 0.0f) * t);
    return new float[]{(float) Math.cos(dNormalizeAngle), (float) Math.sin(dNormalizeAngle)};
}
